// NewService creates a new Service instance.
func NewService(repo Repository, logger Logger) *Service {
    return &Service{
        repo:   repo,
        logger: logger,
        config: DefaultConfig(),
    }
}

// Ensure MyType implements MyInterface at compile time.
var _ MyInterface = (*MyType)(nil)

func (m *MyType) Method1() error {
    // implementation
}

func (m *MyType) Method2(ctx context.Context) (Result, error) {
    // implementation
}

result, err := someFunction()
if err != nil {
    return nil, fmt.Errorf("failed to do something: %w", err)
}

func (s *Service) Process(ctx context.Context, input Input) (Output, error) {
    // Add timeout if needed
    ctx, cancel := context.WithTimeout(ctx, 30*time.Second)
    defer cancel()

    // Check for cancellation
    select {
    case <-ctx.Done():
        return Output{}, ctx.Err()
    default:
    }

    // Pass context to dependencies
    data, err := s.repo.Fetch(ctx, input.ID)
    if err != nil {
        return Output{}, fmt.Errorf("fetch failed: %w", err)
    }

    return s.process(ctx, data), nil
}
